INSERT INTO drop_data (dropperid, itemid, minimum_quantity, maximum_quantity, questid, chance)
SELECT 9300018, 4000142, 1, 1, 1018, 1000000 FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM drop_data WHERE dropperid = 9300018 AND itemid = 4000142);

UPDATE drop_data SET minimum_quantity = 76,  maximum_quantity = 114 WHERE dropperid = 3110100 AND itemid = 0;
